import { sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, timestampColumns } from "./_shared";

/** Users are global, not tenant-scoped: one account can join many orgs. */
export const users = sqliteTable(
  "users",
  {
    id: idColumn(),
    email: text("email").notNull(),
    name: text("name").notNull(),
    passwordHash: text("password_hash").notNull(),
    avatarUrl: text("avatar_url"),
    timezone: text("timezone").notNull().default("UTC"),
    emailVerifiedAt: text("email_verified_at"),
    ...timestampColumns,
  },
  (table) => [uniqueIndex("users_email_idx").on(table.email)],
);

export const sessions = sqliteTable(
  "sessions",
  {
    id: idColumn(),
    userId: text("user_id").notNull(),
    activeOrgId: text("active_org_id"),
    tokenHash: text("token_hash").notNull(),
    expiresAt: text("expires_at").notNull(),
    ...timestampColumns,
  },
  (table) => [uniqueIndex("sessions_token_idx").on(table.tokenHash)],
);

export const passwordResetTokens = sqliteTable("password_reset_tokens", {
  id: idColumn(),
  userId: text("user_id").notNull(),
  tokenHash: text("token_hash").notNull(),
  expiresAt: text("expires_at").notNull(),
  usedAt: text("used_at"),
  ...timestampColumns,
});
    return {};
  } catch {
    return {};
  }
}

export function toUser(row: UserRow): User {
  return {
    id: brandId<UserId>(row.id),
    email: row.email,
    name: row.name,
    avatarUrl: row.avatarUrl,
    timezone: row.timezone,
    emailVerifiedAt: brandStampOrNull(row.emailVerifiedAt),
    createdAt: brandStamp(row.createdAt),
    updatedAt: brandStamp(row.updatedAt),
  };
}

export function toOrganization(row: OrganizationRow): Organization {
  return {
    id: brandId<OrgId>(row.id),
    name: row.name,
    slug: row.slug,
    ownerId: brandId<UserId>(row.ownerId),
    plan: row.plan,
    logoUrl: row.logoUrl,
    trialEndsAt: brandStampOrNull(row.trialEndsAt),
    settings: {
      defaultIssueStatus: row.defaultIssueStatus,
      allowPublicProjects: row.allowPublicProjects,
      requireTwoFactor: row.requireTwoFactor,
      digestHourUtc: row.digestHourUtc,
      enabledFlagOverrides: parseJsonArray<string>(row.enabledFlagOverrides),
    },
    createdAt: brandStamp(row.createdAt),
    updatedAt: brandStamp(row.updatedAt),
    archivedAt: brandStampOrNull(row.archivedAt),
  };
}

/**
 * ULID generation and validation. Every branded id in the app is produced
 * here, so ids sort lexicographically by creation time and the repositories
 * can use them as pagination cursors without a separate sort column.
 */
/** Crockford base32, minus I, L, O and U. */
const ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
const TIME_LENGTH = 10;
const RANDOM_LENGTH = 16;

const ULID_PATTERN = /^[0-9A-HJKMNP-TV-Z]{26}$/;

function encodeTime(time: number): string {
  let remaining = time;
  let out = "";
  for (let i = 0; i < TIME_LENGTH; i += 1) {
    const mod = remaining % 32;
    out = ALPHABET[mod] + out;
    remaining = (remaining - mod) / 32;
  }
  return out;
}

function encodeRandom(next: () => number): string {
  let out = "";
  for (let i = 0; i < RANDOM_LENGTH; i += 1) {
    out += ALPHABET[next() % 32];
  }
  return out;
}
/**
 * Shared query helpers: cursor encoding, `orgId` predicate construction and the archived-row predicate every other repository composes.
 *
 * Must call (do not reimplement): shouldFilterArchived
 */
import { eq, isNull } from "drizzle-orm";
import { shouldFilterArchived } from "@/lib/soft-delete";
import type { ArchiveScope, OrgId } from "@/types/common";
import type { SQL } from "drizzle-orm";
import type { SQLiteColumn } from "drizzle-orm/sqlite-core";

const CURSOR_SEPARATOR = "|";

/**
 * Cursors are opaque to callers: base64url of `<sortValue>|<id>`. Encoding the
 * sort value alongside the id is what lets `listX` resume from a stable point
 * even when two rows share a timestamp.
 */
export function encodeCursor(id: string, sortValue: string): string {
  return Buffer.from(`${sortValue}${CURSOR_SEPARATOR}${id}`, "utf8").toString(
    "base64url",
  );
}

export function decodeCursor(
  cursor: string,
): { id: string; sortValue: string } | null {
  let decoded: string;
  try {
    decoded = Buffer.from(cursor, "base64url").toString("utf8");
  } catch {
    return null;
  }

