import * as memberRepo from "@/server/repositories/member-repository";
import * as orgs from "@/server/services/organization-service";
import * as members from "@/server/services/member-service";
import * as billing from "@/server/services/billing-service";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as activityRepo from "@/server/repositories/activity-repository";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("handover", () => {
  it("works end to end", async () => {
    const off = registerActivityListeners();
    const t = await createTenant("ho1");
    const other = await createTenant("ho2");
    await expect(orgs.initiateOwnershipHandover(t.actors.admin, t.org.id, t.userIds.member)).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(orgs.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.owner)).rejects.toMatchObject({ reason: "self" });
    await expect(orgs.initiateOwnershipHandover(t.actors.owner, t.org.id, other.userIds.admin)).rejects.toBeInstanceOf(NotFoundError);
    await expect(orgs.initiateOwnershipHandover(t.actors.owner, other.org.id, other.userIds.admin)).rejects.toBeInstanceOf(TenantScopeError);
    const h = await orgs.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.member);
    expect(Date.parse(h.expiresAt) - Date.parse(h.createdAt)).toBe(7 * 86400000);
    const notes = await notificationRepo.listNotifications({ orgId: t.org.id, recipientId: t.userIds.member, unreadOnly: false, limit: 10, cursor: null } as never);
    expect(notes.items.map((n) => n.kind)).toContain("ownership_handover");
    await expect(orgs.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.admin)).rejects.toMatchObject({ reason: "pending_exists" });
    expect(await orgs.getPendingOwnershipHandover(t.actors.viewer, t.org.id)).toMatchObject({ toUserId: t.userIds.member });
    expect(await orgs.getPendingOwnershipHandover(other.actors.viewer, other.org.id)).toBeNull();
    await expect(orgs.acceptOwnershipHandover(t.actors.admin, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });
    const seen: unknown[] = [];
    const o1 = subscribe("member.role_changed", (p) => { seen.push(p); });
    const o2 = subscribe("organization.ownership_transferred", (p) => { seen.push(p); });
    const org = await orgs.acceptOwnershipHandover(t.actors.member, t.org.id);
    o1(); o2();
    expect(org.ownerId).toBe(t.userIds.member);
    expect(seen).toHaveLength(3);
    console.log(JSON.stringify(seen));
    expect((await memberRepo.findMember(t.org.id, t.userIds.owner))?.role).toBe("admin");
    expect((await memberRepo.findMember(t.org.id, t.userIds.member))?.role).toBe("owner");
    await expect(orgs.acceptOwnershipHandover(t.actors.member, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });
    await expect(billing.changePlan(t.actors.owner, { orgId: t.org.id, plan: "enterprise", interval: "monthly" })).rejects.toBeInstanceOf(PermissionDeniedError);
    await billing.changePlan(t.actors.member, { orgId: t.org.id, plan: "enterprise", interval: "monthly" });
    const act = await activityRepo.listActivity({ orgId: t.org.id, limit: 50, cursor: null } as never);
    console.log(JSON.stringify(act.items.map((a) => [a.action, a.subjectKind, a.metadata])));
    const prev = await memberRepo.findMember(t.org.id, t.userIds.owner);
    await members.removeMember({ ...t.actors.member, role: "owner" }, { orgId: t.org.id, memberId: prev!.id });
    expect(toAppError(new OwnershipHandoverError("expired")).code).toBe("conflict");
    off();
  });

  it("expiry and auto-withdraw", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    const t = await createTenant("ho3");
    const T = new Date("2030-01-01T00:00:00.000Z");
    vi.setSystemTime(T);
    await orgs.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.viewer);
    vi.setSystemTime(new Date(T.getTime() + 7 * 86400000 - 1));
    expect(await orgs.getPendingOwnershipHandover(t.actors.viewer, t.org.id)).not.toBeNull();
    vi.setSystemTime(new Date(T.getTime() + 7 * 86400000));
    expect(await orgs.getPendingOwnershipHandover(t.actors.viewer, t.org.id)).toBeNull();
    await expect(orgs.acceptOwnershipHandover(t.actors.viewer, t.org.id)).rejects.toMatchObject({ reason: "expired" });
    await expect(orgs.cancelOwnershipHandover(t.actors.owner, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });
    await orgs.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.viewer);
    const vm = await memberRepo.findMember(t.org.id, t.userIds.viewer);
    await members.removeMember(t.actors.owner, { orgId: t.org.id, memberId: vm!.id });
    expect(await orgs.getPendingOwnershipHandover(t.actors.owner, t.org.id)).toBeNull();
    vi.useRealTimers();
  });
});
